/// The menu a right-click opens: making a file or folder in `folder`, and for
/// an entry at `path`, renaming or deleting it.
fn entry_menu(
    menu: PopupMenu,
    tree: &WeakEntity<ProjectTree>,
    folder: PathBuf,
    path: Option<PathBuf>,
) -> PopupMenu {
    let item = |label: &'static str, icon: IconName, naming: Naming| {
        let tree = tree.clone();
