            .icon(icon)
            .on_click(move |_, window, cx| {
                // After the menu has closed, so the input keeps focus.
                let (tree, naming) = (tree.clone(), naming.clone());
                window.defer(cx, move |window, cx| {
                    tree.update(cx, |tree, cx| tree.start_naming(naming, window, cx))
                        .ok();
                });
            })
    };
