        .item(item("New File…", IconName::FilePlus, Naming::NewFile(folder.clone())))
        .item(item("New Folder…", IconName::FolderPlus, Naming::NewFolder(folder)));
    let Some(path) = path else {
        return menu;
    };
    let delete = {
        let (tree, path) = (tree.clone(), path.clone());
        PopupMenuItem::new("Delete")
            .icon(IconName::Trash2)
            .on_click(move |_, window, cx| {
                tree.update(cx, |tree, cx| tree.confirm_delete(path.clone(), window, cx))
                    .ok();
            })
    };
    menu.separator()
        .item(item("Rename…", IconName::Pencil, Naming::Rename(path)))
        .item(delete)
}""")
