/// The menu a right-click opens: making a file or folder in `folder`, and for
/// an entry at `path`, renaming or deleting it.
fn entry_menu(
    menu: PopupMenu,
    tree: &WeakEntity<ProjectTree>,
    folder: PathBuf,
    path: Option<PathBuf>,
) -> PopupMenu {
    let item = |label: &'static str, icon: IconName, naming: Naming| {
        let tree = tree.clone();
        PopupMenuItem::new(label)
            .icon(icon)
            .on_click(move |_, window, cx| {
                // After the menu has closed, so the input keeps focus.
                let (tree, naming) = (tree.clone(), naming.clone());
                window.defer(cx, move |window, cx| {
                    tree.update(cx, |tree, cx| tree.start_naming(naming, window, cx))
                        .ok();
                });
            })
    };
    let menu = menu
        .item(item("New File…", IconName::FilePlus, Naming::NewFile(folder.clone())))
        .item(item("New Folder…", IconName::FolderPlus, Naming::NewFolder(folder)));
    let Some(path) = path else {
        return menu;
    };
    let delete = {
        let (tree, path) = (tree.clone(), path.clone());
        PopupMenuItem::new("Delete")
            .icon(IconName::Trash2)
            .on_click(move |_, window, cx| {
                tree.update(cx, |tree, cx| tree.confirm_delete(path.clone(), window, cx))
                    .ok();
            })
    };
    menu.separator()
        .item(item("Rename…", IconName::Pencil, Naming::Rename(path)))
        .item(delete)
}""")
